CREATE SCHEMA studio;
CREATE TABLE studio.documents(kind TEXT NOT NULL, name TEXT NOT NULL, version BIGINT NOT NULL, payload JSONB NOT NULL, created_ms BIGINT NOT NULL, PRIMARY KEY(kind,name,version));
CREATE TABLE studio.alerts(id BIGSERIAL PRIMARY KEY,payload JSONB NOT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE,last_condition BOOLEAN NOT NULL DEFAULT FALSE,last_bar BIGINT NOT NULL DEFAULT 0,last_sent BIGINT NOT NULL DEFAULT 0,error TEXT);
CREATE TABLE studio.deliveries(id BIGSERIAL PRIMARY KEY,alert_id BIGINT REFERENCES studio.alerts(id),ts BIGINT NOT NULL,payload JSONB NOT NULL,read BOOLEAN NOT NULL DEFAULT FALSE,UNIQUE(alert_id,ts));
CREATE TABLE studio.providers(name TEXT PRIMARY KEY,payload JSONB NOT NULL,received_ms BIGINT NOT NULL,error TEXT);
CREATE TABLE studio.news(id TEXT PRIMARY KEY,provider TEXT NOT NULL,title TEXT NOT NULL,url TEXT NOT NULL,published_ms BIGINT NOT NULL,first_seen_ms BIGINT NOT NULL,assets JSONB NOT NULL);
CREATE TABLE studio.decisions(id BIGSERIAL PRIMARY KEY,created_ms BIGINT NOT NULL,payload JSONB NOT NULL);
CREATE TABLE studio.ai_budget(id INTEGER PRIMARY KEY CHECK(id=1),budget NUMERIC NOT NULL CHECK(budget>=0),spent NUMERIC NOT NULL DEFAULT 0,reserved NUMERIC NOT NULL DEFAULT 0,enabled BOOLEAN NOT NULL DEFAULT FALSE,failures INTEGER NOT NULL DEFAULT 0,blocked_until BIGINT NOT NULL DEFAULT 0);
INSERT INTO studio.ai_budget(id,budget) VALUES(1,0);

CREATE TABLE studio.deployments(bot_id TEXT PRIMARY KEY,name TEXT NOT NULL,version BIGINT NOT NULL,created_ms BIGINT NOT NULL);
